root = Stack([TextExplanation, Diagram])

TextExplanation = Text(
  "The dot product of two vectors measures how much one vector extends in the direction of another. "
  "Geometrically, it equals the product of their lengths and the cosine of the angle between them. "
  "If the vectors are orthogonal (at 90°), their dot product is zero, indicating no directional overlap. "
  "A negative dot product means the projection of one vector onto the other points opposite to the vector's direction."
)

Diagram = Graphic("DotProductDiagram", [
  group([
    // Vector A from origin
    path("M 50 100 L 150 50",),
    text(155, 45, "Vector A"),
    // Vector B at angle theta
    path("M 50 100 L 130 120",),
    text(135, 125, "Vector B"),
    // Projection of B onto A (dashed line)
    path("M 130 120 L 130 80",),
    path("M 130 80 L 150 50", "stroke-dasharray:4,2"),
    text(140, 75, "Projection of B on A"),
    // Right angle marker
    path("M 130 80 L 135 80 L 135 85"),
    // Angle theta label
    text(90, 90, "θ"),
    // Orthogonal vector example (Vector C)
    path("M 250 100 L 300 50",),
    text(305, 45, "Vector C"),
    path("M 250 100 L 250 150",),
    text(255, 155, "Vector D (orthogonal to C)"),
    // Right angle marker for orthogonal vectors
    path("M 250 150 L 255 150 L 255 145"),
    // Negative projection example
    path("M 350 100 L 400 50",),
    text(405, 45, "Vector E"),
    path("M 350 100 L 310 80",),
    text(305, 75, "Vector F"),
    // Projection of F onto E (dashed line, opposite direction)
    path("M 310 80 L 350 100", "stroke-dasharray:4,2"),
    text(330, 90, "Negative projection")
  ])
])

